sql_calls.sql:
SELECT COUNT(*) as complaint_count
FROM payments.customer_complaints
WHERE complaint_ts >= '2026-06-01' AND complaint_ts < '2026-07-01';

SELECT sku, name, pack, price_inr, cost_inr
FROM store.products
ORDER BY sku;

SELECT COUNT(*) as total, COUNT(bill_ref) as with_bill_ref
FROM payments.psp_upi_report
WHERE initiated_ts >= '2026-06-01' AND initiated_ts < '2026-07-01';

SELECT *
FROM store.shelf_audits
LIMIT 20;

SELECT DISTINCT sku
FROM store.shelf_audits
ORDER BY sku;

SELECT COUNT(*) as total_attempts
FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT sku, name, pack, flow, price_inr, cost_inr
FROM store.products
ORDER BY name;

SELECT SUM(amount_inr) AS fraud_amount
FROM payments.upi_refunds
WHERE requested_ts >= '2026-06-01' AND requested_ts < '2026-07-01';

SELECT COUNT(*) AS shipment_count
FROM warehouse.shipments
WHERE dispatched_ts >= '2026-06-01' AND dispatched_ts < '2026-07-01';

SELECT COUNT(DISTINCT bill_id) as distinct_bills
FROM store.pos_lines
WHERE bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01';

SELECT SUM(net_inr) as total_net_upi
FROM payments.upi_settlements
WHERE settlement_date >= '2026-06-01' AND settlement_date < '2026-07-01';

SELECT COUNT(*) as refund_count, SUM(amount_inr) as total_amount
FROM payments.upi_refunds
WHERE requested_ts >= '2026-06-01' AND requested_ts < '2026-07-01';

SELECT product_id, product_name, unit, selling_price
FROM store.products
WHERE product_name ILIKE '%atta%' AND unit ILIKE '%5%kg%';

SELECT sku, name, pack, price_inr
FROM store.products
WHERE name ILIKE '%atta%' AND pack ILIKE '%5%kg%';

SELECT *
FROM store.store_orders
WHERE order_id = 'SO-260625';

SELECT *
FROM store.daily_sales
LIMIT 10;

SELECT DISTINCT EXTRACT(YEAR FROM date)::int AS year
FROM store.daily_sales
ORDER BY year;

SELECT DISTINCT EXTRACT(YEAR FROM bill_ts)::int AS year
FROM store.pos_lines
ORDER BY year;

SELECT COUNT(DISTINCT bill_id) AS transactions
FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01' AND till_status = 'success';

SELECT COUNT(DISTINCT bill_id) AS transactions
FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01' AND till_status = 'approved';

SELECT COUNT(DISTINCT order_id) AS store_orders_jun26
FROM store.store_orders
WHERE created_ts >= '2026-06-01' AND created_ts < '2026-07-01';

SELECT sku, price_inr
FROM store.products
WHERE sku = 'ATTA-WW-5KG';
